import type { Dnd5eSpell } from '../../types';

/**
 * Every spell in the System Reference Document 5.2 (2024 rules, CC-BY-4.0),
 * summarised in plain words as reminders. Class lists follow the 2024 lists.
 *
 * Rows are compact: `S(level, name, school, casting time, range, components,
 * duration, classes, text, higher?)`. Concentration is read from a duration
 * that starts with "C " and ritual from a casting time that mentions "Ritual".
 */

const SCHOOLS: Record<string, string> = {
  A: 'Abjuration',
  C: 'Conjuration',
  D: 'Divination',
  En: 'Enchantment',
  Ev: 'Evocation',
  I: 'Illusion',
  N: 'Necromancy',
  T: 'Transmutation',
};

const CLASS_CODES: Record<string, string> = {
  b: 'bard',
  c: 'cleric',
  d: 'druid',
  p: 'paladin',
  r: 'ranger',
  s: 'sorcerer',
  k: 'warlock',
  w: 'wizard',
};

const TIMES: Record<string, string> = {
  A: 'Action',
  BA: 'Bonus Action',
  AR: 'Action or Ritual',
  SMITE: 'Bonus Action, immediately after you hit a target with a Melee weapon or an Unarmed Strike',
};

function spellId(name: string): string {
  return name
    .toLowerCase()
    .replace(/['’]/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '');
}

function S(
  level: number,
  name: string,
  school: string,
  time: string,
  range: string,
  components: string,
  duration: string,
  classes: string,
  text: string,
  higher?: string,
): Dnd5eSpell {
  const castingTime = TIMES[time] ?? time;
  const concentration = duration.startsWith('C ');
  const spell: Dnd5eSpell = {
    id: spellId(name),
    name,
    level,
    school: SCHOOLS[school] ?? school,
    castingTime,
    range,
    components,
    duration: duration === 'I' ? 'Instantaneous' : concentration ? `Concentration, up to ${duration.slice(2)}` : duration,
    concentration,
    ritual: castingTime.includes('Ritual'),
    classes: classes.split('').map((c) => CLASS_CODES[c] ?? c),
    text,
  };
  if (higher) spell.higher = higher;
  return spell;
}

const CANTRIP = (die: string) => `Damage rises to 2${die} at level 5, 3${die} at 11 and 4${die} at 17.`;
const SLOT = (what: string) => `${what} for each slot level above the spell's level.`;

